local shape_chunks = {}
for i = 1, 7 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.ConflictException = errors.define({ tag = "ConflictException", categories = {} })
classes.EndpointAlreadyExists = errors.define({
  tag = "EndpointAlreadyExists",
  categories = { "AlreadyExistsError", "ConflictError" },
})
classes.EndpointConfigAlreadyExists = errors.define({
  tag = "EndpointConfigAlreadyExists",
  categories = { "AlreadyExistsError", "ConflictError" },
})
classes.EndpointConfigNotFound = errors.define({
  tag = "EndpointConfigNotFound",
  categories = { "NotFoundError" },
})
classes.EndpointNotFound = errors.define({
  tag = "EndpointNotFound",
  categories = { "NotFoundError" },
})
classes.ModelAlreadyExists = errors.define({
  tag = "ModelAlreadyExists",
  categories = { "AlreadyExistsError", "ConflictError" },
})
classes.ModelNotFound = errors.define({ tag = "ModelNotFound", categories = { "NotFoundError" } })
classes.ResourceInUse = errors.define({
  tag = "ResourceInUse",
  categories = { "DependencyViolationError" },
})
classes.ResourceLimitExceeded = errors.define({
  tag = "ResourceLimitExceeded",
  categories = { "ThrottlingError" },
})
classes.ResourceNotFound = errors.define({ tag = "ResourceNotFound", categories = {} })

local ops = {}
for i = 1, 2 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "aws.sagemaker",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "aws-api",
    prefix = "SageMaker",
    service = "SageMaker",
    templates = false,
    propagate = "xray",
    response_headers = {
      { header = "x-amzn-requestid", name = "aws.request_id" },
      { header = "x-amz-request-id", name = "aws.request_id" },
      { header = "x-amzn-request-id", name = "aws.request_id" },
      { header = "x-amz-id-2", name = "aws.extended_request_id" },
    },
  },
}
